import sys
from collections import defaultdict

MOD = 1000000007

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def main():
    n = int(sys.stdin.readline().strip())
    edges = defaultdict(list)
    for _ in range(n - 1):
        u, v = read_ints()
        edges[u].append(v)
        edges[v].append(u)

    decorations = read_ints()

    # Initialize DP table
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    def dfs(node, parent):
        if decorations[node - 1] != 0:
            dp[node][decorations[node - 1]] = 1

        for child in edges[node]:
            if child == parent:
                continue
            dfs(child, node)
            for i in range(1, n + 1):
                if dp[child][i] > 0:
                    for j in range(1, n + 1):
                        if dp[node][j] > 0:
                            dp[node][i] += dp[child][i] * dp[node][j]
                            dp[node][i] %= MOD

    dfs(1, -1)

    result = sum(dp[1]) % MOD
    print(result)

if __name__ == "__main__":
    main()
